'use strict';
(() => {
const EXPERIMENTS=window.TRACE_EXPERIMENTS, C=window.TRACE_COMPARISON, app=document.querySelector('#app');
let D=EXPERIMENTS?.cap17;
if(!D){app.innerHTML='<div class="empty">The data export is missing. Run the exporter described in demo_ui/README.md.</div>';return;}
const METHODS=[
 ['paper_nibs_cos_max','NIBS Max','#248d90'],['paper_nibs_cos_mean','NIBS Mean','#416eae'],
 ['paper_gibs_pdf','Paper GIBS','#8b80b6'],['c4_gibs','C4 GIBS','#d4a34a'],
 ['tool_sim_nibs','tool_sim','#8499a8'],['last_step_first','Last-step-first','#9faab4'],['random_expected','Random expectation','#c2cbd0']
];
const names=Object.fromEntries(METHODS.map(m=>[m[0],m[1]])), colors=Object.fromEntries(METHODS.map(m=>[m[0],m[2]]));
const S={page:'comparison',experiment:'cap17',example:null,scope:'tool_calls',population:'common',seed:'mean',metric:'macro_auroc',task:'all',outcome:'all',search:'',run:null,tab:'steps',step:0,runSeed:'7',teacher:'paper_gibs_pdf',ref:0,onlyLabeled:false,sort:'id'};
const E=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const json=v=>E(JSON.stringify(v,null,2));
const num=(v,n=3)=>v==null?'N/A':Number(v).toFixed(n);
const pct=v=>v==null?'N/A':`${(100*v).toFixed(1)}%`;
const val=(a,key,task=false)=>key==='macro_auroc'?a?.[task?'auroc_error_positive':'macro_auroc']:a?.localization?.[key];
const mean=a=>a.length?a.reduce((x,y)=>x+y,0)/a.length:null;
const sd=a=>a.length?Math.sqrt(mean(a.map(x=>(x-mean(a))**2))):null;
const metricFmt=(v,key=S.metric)=>key==='macro_auroc'?num(v):pct(v);
const badge=(t,k='')=>`<span class="badge ${k}">${E(t)}</span>`;
const title=(eyebrow,heading,description,action='')=>`<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${heading}</h1><p class="intro">${description}</p></div>${action}</div>`;
const option=(v,label,current)=>`<option value="${E(v)}" ${v===current?'selected':''}>${E(label)}</option>`;
const stat=(number,label,small='')=>`<div class="stat"><div class="number">${number}</div><div class="label">${label}</div>${small?`<div class="small-label">${small}</div>`:''}</div>`;
const taskById=id=>D.tasks.find(t=>t.id===id);
const getIndex=id=>D.runs.find(r=>r.id===id);
const isLearned=m=>m==='paper_gibs_pdf'||m==='c4_gibs';
const score=(step,method,seed=S.runSeed)=>{const v=step.scores[method];return v&&typeof v==='object'?v[seed]:v;};
function metrics(method,task=null){
 let datasets=[];
 if(isLearned(method)){
  const source=D.summary[S.population==='common'?'learned_common':'learned_all'][method];
  datasets=(S.seed==='mean'?['7','17','27']:[S.seed]).map(seed=>task?source[seed][S.scope].tasks[task]:source[seed][S.scope].aggregate);
 } else {
  if(S.population==='all')return {value:null,std:null,n:0,detail:null};
  const source=D.summary.baselines[method][S.scope];datasets=[task?source.tasks[task]:source.aggregate];
 }
 const values=datasets.map(a=>val(a,S.metric,task!==null)).filter(x=>x!=null);
 return {value:mean(values),std:values.length>1?sd(values):null,n:values.length,detail:datasets[0]};
}
function navigate(page,run=null){
 if(run){S.run=run;S.step=0;S.ref=0;}
 const query=new URLSearchParams({experiment:S.experiment});if(run)query.set('run',run);if(S.example)query.set('example',S.example);
 const hash=page+'?'+query;
 if(location.hash.slice(1)===hash){S.page=page;render();}else location.hash=hash;
}
function decodeRoute(){const [p,q]=(location.hash.slice(1)||'comparison').split('?'),params=new URLSearchParams(q||'');S.page=['comparison','overview','explorer','diagnosis','guide'].includes(p)?p:'comparison';const experiment=params.get('experiment');if(EXPERIMENTS[experiment])S.experiment=experiment;D=EXPERIMENTS[S.experiment];S.example=params.get('example');const r=params.get('run');if(r&&getIndex(r)){const changed=S.run!==r;S.run=r;S.task=getIndex(r).task;const example=C.examples.find(e=>e.id===S.example&&e.run_id===r);if(changed&&example){S.step=example.cap17.error_step;S.runSeed=example.seed;}}}
function bind(id,event,fn){document.getElementById(id)?.addEventListener(event,fn);}
function toast(message){const t=document.getElementById('toast');t.textContent=message;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),3000);}
function render(){
 document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===S.page));
 document.getElementById('breadcrumb').textContent={comparison:'3–5 vs 3–17',overview:'Results overview',explorer:'Trajectory explorer',diagnosis:'Why these results?',guide:'Method walkthrough'}[S.page];
 document.getElementById('source-stamp').textContent=D.meta.experiment_label+' · Frozen input '+D.meta.snapshot_sha256.slice(0,12);
 document.getElementById('experiment').value=S.experiment;
 if(S.page==='comparison')comparison();else if(S.page==='overview')overview();else if(S.page==='explorer')explorer();else if(S.page==='diagnosis')diagnosis();else guide();
}
function changeExperiment(experiment){
 if(!EXPERIMENTS[experiment])return;
 const step=S.step;S.experiment=experiment;D=EXPERIMENTS[experiment];S.ref=0;
 navigate(S.page,S.page==='explorer'?S.run:null);S.step=step;
}
function openExample(id,tab='steps'){
 const example=C.examples.find(e=>e.id===id);if(!example)return;
 S.experiment='cap17';D=EXPERIMENTS.cap17;S.example=id;S.task=example.task;S.outcome='all';S.search='';S.runSeed='7';S.tab=tab;S.teacher='paper_gibs_pdf';
 navigate('explorer',example.run_id);S.step=example.cap17.error_step;
}
const signed=(value,percent=false)=>value==null?'N/A':`${value>0?'+':''}${(value*(percent?100:1)).toFixed(percent?1:3)}${percent?' pp':''}`;
function comparison(){
 const scope=C.scopes[S.scope],primary=C.scopes.tool_calls,g=primary.paper_gibs_pdf,c=primary.c4_gibs;
 const table=METHODS.map(([key,label,color])=>{const a=scope[key].auroc,t=scope[key].top1;
  return `<tr data-comparison-method="${key}"><td><span class="method-name"><i style="background:${color}"></i>${label}</span></td><td class="number">${num(a.five.mean)}${isLearned(key)?`<small>± ${num(a.five.std)}</small>`:''}</td><td class="number">${num(a.trial.mean)}${isLearned(key)?`<small>± ${num(a.trial.std)}</small>`:''}</td><td class="number delta ${a.delta>0?'positive':a.delta<0?'negative':''}">${signed(a.delta)}</td><td class="number">${pct(t.five.mean)}</td><td class="number">${pct(t.trial.mean)}</td><td class="number delta ${t.delta>0?'positive':t.delta<0?'negative':''}">${signed(t.delta,true)}</td></tr>`;
 }).join('');
 const cards=C.examples.map((e,i)=>`<article class="example-card"><div class="row-between"><span class="eyebrow">CASE ${String(i+1).padStart(2,'0')} / TASK ${e.task}</span>${badge('Real saved run','neutral')}</div><h3>${E(e.title)}</h3><p class="example-goal">${E(e.goal)}</p><p><b>What is flagged:</b> ${E(e.plain_error)}</p><p>${E(e.explanation)}</p><div class="caption">Seed 7 · ${e.tool_steps} tool calls · first labelled error: step ${e.cap17.error_step+1}</div><div class="example-actions"><button class="primary" data-example="${e.id}">Inspect graph & scores →</button><button class="button" data-example-mcs="${e.id}">See MCS targets</button></div></article>`).join('');
 app.innerHTML=title('CONTROLLED COMPARISON / SAME 1,000 TRAJECTORIES','What changes when we add references?','Minimum three in both settings. Maximum five versus maximum seventeen. Same data, task-group folds, seeds, graph model and evaluation labels.',`<a class="button" href="data/COMPARISON_REPORT.md" download>↓ Download comparison + examples</a>`)+
 `<div class="comparison-hero"><div class="hero-finding"><div class="eyebrow">MAIN TOOL-CALL FINDING / GIBS</div><h2>${pct(g.top1.five.mean)} <span>→</span> ${pct(g.top1.trial.mean)}</h2><p>First-error Top-1 improves by <b>${signed(g.top1.delta,true)}</b>. AUROC ${num(g.auroc.five.mean)} → ${num(g.auroc.trial.mean)}.</p></div><div class="hero-finding amber"><div class="eyebrow">MAIN TOOL-CALL FINDING / C4</div><h2>${pct(c.top1.five.mean)} <span>→</span> ${pct(c.top1.trial.mean)}</h2><p>First-error Top-1 decreases by <b>${Math.abs(100*c.top1.delta).toFixed(1)} pp</b>. AUROC ${num(c.auroc.five.mean)} → ${num(c.auroc.trial.mean)}.</p></div></div>
 <div class="stats compact">${stat('1,000','Same saved trajectories','50 tasks × 20 runs; no new generation')}${stat('860','Targets per method, per setting','Actual cap-17 training references: 3–16')}${stat('48','GCN checkpoints across both settings','24 trained from scratch per experiment')}</div>
 <section class="panel"><div class="panel-title"><div><h2>Both settings, on the same comparison population</h2><p class="caption">911 common runs. Tool AUROC: 26 tasks with both label classes. Tool localization: 173 failed runs with a labelled error. Learned scores are means across seeds 7, 17, 27; AUROC also shows the seed standard deviation.</p></div><label class="control"><span>Metric scope</span><select id="comparison-scope">${option('tool_calls','Tool calls',S.scope)}${option('all_agent_steps','All agent steps',S.scope)}</select></label></div><div class="table-scroll"><table class="metrics-table comparison-table"><thead><tr><th>Method</th><th class="number">3–5 AUROC</th><th class="number">3–17 AUROC</th><th class="number">Δ AUROC</th><th class="number">3–5 Top-1</th><th class="number">3–17 Top-1</th><th class="number">Δ Top-1</th></tr></thead><tbody>${table}</tbody></table></div><p class="caption top-space">Higher is better. “pp” means percentage points. Exact values determine deltas, so rounded columns can look equal. These are our τ² Airline measurements, not numbers copied from the paper. Differences are descriptive; no statistical significance test was performed.</p></section>
 <div class="explain-grid"><article class="explain-card"><span class="proof">MEASURED / TOOL CALLS</span><h3>Direct methods remain strong</h3><p><b>tool_sim</b> has the highest tool AUROC (${num(primary.tool_sim_nibs.auroc.trial.mean)}). <b>NIBS Mean</b> has the highest first-error Top-1 (${pct(primary.paper_nibs_cos_mean.top1.trial.mean)}). The last-step baseline (${pct(primary.last_step_first.top1.trial.mean)}) also beats both learned models at localization.</p></article><article class="explain-card"><span class="proof hypothesis">INTERPRETATION / NEEDS DIAGNOSIS</span><h3>More agreement is not always more correctness</h3><p>Additional references change the averaged MCS targets and therefore the learned supervision. GIBS improved in this experiment; C4 declined. Whether extra matches strengthen useful patterns or reinforce misleading similarities needs per-run inspection and human review.</p></article></div>
 <div class="callout"><p><b>Reference count is not the pass/fail balance.</b> These references are successful runs used for comparison. A cap of 17 does not force 17 references; training queries here have 3–16 eligible successes. NIBS uses a larger evaluation reference bank. Learned inference receives only the query graph.</p></div>
 <section class="top-space" id="demo-examples"><div class="panel-title"><div><div class="eyebrow">FIVE ACTUAL DEMONSTRATION CASES</div><h2>Show the evidence, one execution at a time.</h2><p class="caption">Selected after evaluation from seed-7, tool-only first-error rankings. These cases illustrate behavior; the full tables above establish performance. Every case is a failed airline run—“GIBS succeeds” means it localizes the error.</p></div></div><div class="examples-grid">${cards}</div></section>
 <section class="panel top-space"><h2>A short route for your presentation</h2><div class="method-flow"><span class="flow-box">1. Read the task</span><span class="flow-arrow">→</span><span class="flow-box">2. Inspect the first labelled error</span><span class="flow-arrow">→</span><span class="flow-box">3. Compare both settings’ scores</span><span class="flow-arrow">→</span><span class="flow-box">4. Show graph & MCS references</span></div><p class="caption">Automatic labels and MCS targets are not human ground truth. The graphs show inferred observed dependencies, not hidden chain-of-thought. Human review, stakeholder feedback and missing ACC@80%/ECE remain separate work.</p><div class="pill-row"><a class="button" href="data/cap5/REPORT.md" download>3–5 report</a><a class="button" href="data/cap17/REPORT.md" download>3–17 report</a><a class="button" href="data/comparison.json" download>Exact comparison + example evidence</a></div></section>`;
 bind('comparison-scope','change',e=>{S.scope=e.target.value;comparison();});
 document.querySelectorAll('[data-example]').forEach(b=>b.addEventListener('click',()=>openExample(b.dataset.example)));
 document.querySelectorAll('[data-example-mcs]').forEach(b=>b.addEventListener('click',()=>openExample(b.dataset.exampleMcs,'mcs')));
}
function overview(){
 const learned=metrics('paper_gibs_pdf'),denom=learned.detail?.localization?.n_failed_queries_with_labelled_error;
 const bars=METHODS.map(([key,label,color])=>{const m=metrics(key);return `<div class="bar-row"><div>${label}</div><div class="bar-track"><div class="bar-fill" style="width:${100*(m.value??0)}%;background:${color}"></div></div><div class="bar-value">${metricFmt(m.value)}</div></div>`;}).join('');
 const rows=METHODS.map(([key,label,color])=>{const m=metrics(key);return `<tr><td><span class="method-name"><i style="background:${color}"></i>${label}</span></td><td class="number">${metricFmt(m.value)}${m.std!=null?`<div class="muted small">± ${metricFmt(m.std)}</div>`:''}</td><td class="number">${isLearned(key)?(S.seed==='mean'?'3 seeds':'Seed '+S.seed):'Direct score'}</td></tr>`;}).join('');
 let tasks=D.tasks.filter(t=>!S.onlyLabeled||metrics('paper_nibs_cos_max',t.id).value!=null);
 if(S.sort==='gap')tasks.sort((a,b)=>Math.abs((metrics('paper_nibs_cos_max',b.id).value??0)-(metrics('paper_gibs_pdf',b.id).value??0))-Math.abs((metrics('paper_nibs_cos_max',a.id).value??0)-(metrics('paper_gibs_pdf',a.id).value??0)));
 app.innerHTML=title('TAU²-BENCH / '+D.meta.experiment_label,'Find the step. Understand the failure.','A working results explorer for the completed NIBS, GIBS and C4 experiment. Every chart below comes from saved benchmark outputs.',`<a class="button" href="data/${S.experiment}/REPORT.md" download>↓ Download report</a>`)+
 `<div class="stats">${stat('1,000','Generated trajectories','20 runs per task')}${stat('50','Airline tasks','680 passes · 320 failures')}${stat('24','Trained GCN checkpoints','2 methods × 4 folds × 3 seeds')}${stat('911','Reference-eligible comparisons','All 1,000 receive learned scores')}</div>
 <div class="filters"><label class="control"><span>Step scope</span><select id="scope">${option('tool_calls','Tool calls',S.scope)}${option('all_agent_steps','All agent steps',S.scope)}</select></label><label class="control"><span>Compared population</span><select id="population">${option('common','Shared reference coverage · 911 runs',S.population)}${option('all','All learned predictions · 1,000 runs',S.population)}</select></label><label class="control"><span>Training seed</span><select id="seed">${option('mean','Mean ± SD over 3 seeds',S.seed)}${['7','17','27'].map(s=>option(s,'Seed '+s,S.seed)).join('')}</select></label></div>
 <div class="cols"><section class="panel"><div class="panel-title"><div><h2>Method comparison</h2><p class="caption">Higher is better. Saved held-out predictions; no fitting happens in this UI.</p></div><div class="segmented"><button id="auc-tab" class="${S.metric==='macro_auroc'?'active':''}">AUROC</button><button id="top-tab" class="${S.metric==='top1'?'active':''}">First-error Top-1</button></div></div><div class="bars">${bars}</div><div class="metric-description">${S.metric==='macro_auroc'?`Macro AUROC separates labelled errors from correct steps across ${learned.detail?.n_tasks_with_both_classes??'eligible'} tasks with both classes. It is not task pass rate.`:`Lowest-confidence first-error localization across ${denom??'eligible'} failed runs with a labelled error. Ties use their expected ranking.`}</div></section>
 <section class="panel"><div class="panel-title"><div><h2>The actual numbers</h2><p class="caption">${S.population==='common'?'Same 911 reference-eligible runs.':'NIBS is unavailable for part of this population; direct baselines are not extrapolated.'}</p></div>${badge('Automatic labels','warn')}</div><table class="metrics-table"><thead><tr><th>Method</th><th class="number">${S.metric==='macro_auroc'?'AUROC':'Top-1'}</th><th class="number">Evaluation</th></tr></thead><tbody>${rows}</tbody></table></section></div>
 <div class="callout"><span>↳</span><p><strong>More references improved GIBS, while C4 scores decreased.</strong> Under 3–17, GIBS has higher tool AUROC than C4, but C4 has higher first-error Top-1. <a href="#comparison">Compare both settings →</a></p></div>
 <section class="panel"><div class="panel-title"><div><h2>All 50 tasks, with coverage intact</h2><p class="caption">Click a task to inspect its executions. N/A means the required label classes or references are missing.</p></div><div class="filters"><label class="small"><input id="label-only" type="checkbox" ${S.onlyLabeled?'checked':''}> Both label classes only</label><select id="task-sort"><option value="id" ${S.sort==='id'?'selected':''}>Task order</option><option value="gap" ${S.sort==='gap'?'selected':''}>Largest NIBS–GIBS gap</option></select></div></div><div class="table-scroll"><table class="metrics-table"><thead><tr><th>Task</th><th>Pass / fail</th><th>Shared runs</th><th class="number">NIBS Max</th><th class="number">NIBS Mean</th><th class="number">GIBS</th><th class="number">C4</th></tr></thead><tbody>${tasks.map(t=>`<tr class="clickable" tabindex="0" data-task="${t.id}" aria-label="Inspect task ${t.id}"><td><b>${t.id.padStart(2,'0')}</b></td><td>${t.passes} / ${t.fails}</td><td>${t.nibs_eligible} / 20</td>${['paper_nibs_cos_max','paper_nibs_cos_mean','paper_gibs_pdf','c4_gibs'].map(k=>`<td class="number">${metricFmt(metrics(k,t.id).value)}</td>`).join('')}</tr>`).join('')}</tbody></table></div></section>`;
 ['scope','population','seed'].forEach(id=>bind(id,'change',e=>{S[id]=e.target.value;overview();}));
 bind('auc-tab','click',()=>{S.metric='macro_auroc';overview();});bind('top-tab','click',()=>{S.metric='top1';overview();});
 bind('label-only','change',e=>{S.onlyLabeled=e.target.checked;overview();});bind('task-sort','change',e=>{S.sort=e.target.value;overview();});
 document.querySelectorAll('[data-task]').forEach(row=>{const go=()=>{S.task=row.dataset.task;S.outcome='all';S.search='';const r=D.runs.find(x=>x.task===S.task&&!x.success&&x.first_error)||D.runs.find(x=>x.task===S.task);navigate('explorer',r.id);};row.addEventListener('click',go);row.addEventListener('keydown',e=>{if(e.key==='Enter')go();});});
}
function loadRun(id,experiment=S.experiment){
 if(!/^[a-f0-9-]{36}$/.test(id)||!getIndex(id))return Promise.reject(Error('Unknown run'));
 if(window.TRACE_RUNS?.[experiment]?.[id])return Promise.resolve(window.TRACE_RUNS[experiment][id]);
 return new Promise((resolve,reject)=>{const script=document.createElement('script');script.src=`data/${experiment}/runs/${id}.js`;script.onload=()=>{script.remove();window.TRACE_RUNS?.[experiment]?.[id]?resolve(window.TRACE_RUNS[experiment][id]):reject(Error('Run asset did not load'));};script.onerror=()=>{script.remove();reject(Error('Could not load this trajectory. Re-export the demo data.'));};document.head.append(script);});
}
function explorer(){
 if(!S.run){S.run=D.meta.presets.nibs_catches;S.task=getIndex(S.run).task;}
 const filtered=D.runs.filter(r=>(S.task==='all'||r.task===S.task)&&(S.outcome==='all'||r.success===(S.outcome==='pass'))&&(!S.search||`${r.task} ${r.id} ${taskById(r.task).goal}`.toLowerCase().includes(S.search.toLowerCase()))).sort((a,b)=>Number(a.task)-Number(b.task)||a.id.localeCompare(b.id));
 if(!filtered.some(r=>r.id===S.run)&&filtered.length)S.run=filtered[0].id;
 app.innerHTML=title('RECORDED RUNS / STEP-LEVEL INSPECTION','Follow one execution.','Inspect actual actions, scores, automatic labels and genuine MCS pair mappings. Select an example or explore any of the 1,000 runs.')+
 `<div class="preset-row">${C.examples.map(e=>`<button class="button" data-case="${e.id}">${E(e.title)}</button>`).join('')}<button class="button" data-preset="successful_run">A successful Task 25 run</button></div><p class="caption">The five comparison cases use seed 7 under 3–17 by default. Switch the active experiment above to inspect the same run under 3–5. All runs remain accessible below.</p>
 <div class="explorer-grid top-space"><aside class="panel run-side"><div class="run-tools"><input id="run-search" type="search" placeholder="Find a run or scenario…" value="${E(S.search)}" aria-label="Search runs"><select id="run-task" aria-label="Task filter">${option('all','All 50 tasks',S.task)}${D.tasks.map(t=>option(t.id,'Task '+t.id+' · '+t.passes+' pass / '+t.fails+' fail',S.task)).join('')}</select><select id="run-outcome" aria-label="Outcome filter">${option('all','All outcomes',S.outcome)}${option('fail','Failed runs',S.outcome)}${option('pass','Passed runs',S.outcome)}</select><span class="count">${filtered.length} executions · reward is run-level only</span></div><div class="run-list">${filtered.map(r=>`<button class="run-card ${r.id===S.run?'active':''}" data-run="${r.id}"><span class="rtitle">Task ${r.task.padStart(2,'0')} ${badge(r.success?'Passed':'Failed',r.success?'':'error')}</span><span class="rmeta">${r.id.slice(0,8)} · ${r.tool_steps} tool calls · ${r.fold}</span></button>`).join('')||'<div class="empty">No matching runs.</div>'}</div></aside><div id="run-content" class="panel">${filtered.length?'<div class="empty">Opening trajectory…</div>':'<div class="empty">Change your filters to see an execution.</div>'}</div></div>`;
 bind('run-task','change',e=>{S.task=e.target.value;explorer();});bind('run-outcome','change',e=>{S.outcome=e.target.value;explorer();});
 bind('run-search','change',e=>{S.search=e.target.value;explorer();});
 document.querySelectorAll('[data-case]').forEach(b=>b.addEventListener('click',()=>openExample(b.dataset.case)));
 document.querySelectorAll('[data-preset]').forEach(b=>b.addEventListener('click',()=>{const id=D.meta.presets[b.dataset.preset];if(!id)return;S.example=null;S.task=getIndex(id).task;S.outcome='all';S.search='';S.tab='steps';navigate('explorer',id);}));
 document.querySelectorAll('[data-run]').forEach(b=>b.addEventListener('click',()=>navigate('explorer',b.dataset.run)));
 const active=document.querySelector('.run-card.active'),list=document.querySelector('.run-list');if(active&&list&&innerWidth>760)list.scrollTop=active.offsetTop-list.offsetTop;
 if(filtered.length)renderRun(S.run);
}
let runToken=0;
async function renderRun(id){
 const token=++runToken,el=document.getElementById('run-content'),experiment=S.experiment;
 try{
 const [data,other]=await Promise.all([loadRun(id,experiment),loadRun(id,experiment==='cap5'?'cap17':'cap5')]);if(token!==runToken||!el||experiment!==S.experiment)return;
 data.comparisonSteps=other.steps;data.comparisonTeachers=other.teachers;
 const r=data.run,t=taskById(r.task);if(S.step>=data.steps.length)S.step=0;
 el.innerHTML=`<div class="run-head"><div><div class="eyebrow">TASK ${E(r.task)} / ${E(r.id.slice(0,8))}</div><h2>${r.success?'A benchmark-successful execution':'A failed execution to investigate'}</h2><p class="goal">${E(t.goal)}</p></div>${badge(r.success?'Reward 1 · Pass':'Reward 0 · Fail',r.success?'':'error')}</div><div class="pill-row">${badge(r.fold+' · held out','purple')}${badge(r.references+' NIBS references',r.nibs_available?'':'warn')}${badge(r.teacher_available?'MCS target available':'No training-reference target',r.teacher_available?'neutral':'warn')}</div>
 ${exampleNote(data)}<div class="row-between"><div class="tabs">${[['steps','Step scores'],['graph','Trajectory graph'],['mcs','MCS & targets'],['transcript','Transcript']].map(([key,label])=>`<button data-tab="${key}" class="${S.tab===key?'active':''}">${label}</button>`).join('')}</div><label class="control"><span>Prediction seed</span><select id="run-seed">${['7','17','27'].map(s=>option(s,'Seed '+s,S.runSeed)).join('')}</select></label></div><div id="run-tab"></div>`;
 bind('focus-example','click',()=>{const e=C.examples.find(e=>e.run_id===id);S.step=e.cap17.error_step;S.runSeed='7';renderRun(id);});
 el.querySelectorAll('[data-tab]').forEach(b=>b.addEventListener('click',()=>{S.tab=b.dataset.tab;renderRun(id);}));
 bind('run-seed','change',e=>{S.runSeed=e.target.value;renderRun(id);});
 if(S.tab==='steps')renderSteps(data);else if(S.tab==='transcript')renderTranscript(data);else if(S.tab==='graph')renderGraph(data);else await renderMCS(data);
 }catch(error){if(el)el.innerHTML=`<div class="empty">${E(error.message)}</div>`;}
}
function exampleNote(data){
 const e=C.examples.find(e=>e.run_id===data.run.id);if(!e)return '';
 const hit=(experiment,method)=>{const r=e[experiment].methods[method];return r.top1===1?'Finds first error':r.top1===0?`Misses · rank ${r.rank_min}${r.rank_max!==r.rank_min?'–'+r.rank_max:''}`:`Tied · ${pct(r.top1)} expected hit`;};
 return `<section class="example-note"><div class="row-between"><div><div class="eyebrow">ACTUAL CASE / ${E(e.kicker)}</div><h3>${E(e.title)}</h3></div>${badge(D.meta.experiment_label)}</div><p><b>What is flagged:</b> ${E(e.plain_error)}</p><p>${E(e.explanation)}</p><div class="table-scroll"><table class="metrics-table"><thead><tr><th>Seed-7 localization</th><th>3–5 references</th><th>3–17 references</th></tr></thead><tbody>${['paper_gibs_pdf','c4_gibs','paper_nibs_cos_mean'].map(m=>`<tr><td>${names[m]}</td><td>${E(hit('cap5',m))}</td><td>${E(hit('cap17',m))}</td></tr>`).join('')}</tbody></table></div><div class="row-between top-space"><p class="caption">Evidence above uses seed 7. Current prediction seed: ${S.runSeed}. Rank 1 means lowest tool confidence; labels are automatic.</p><button class="button" id="focus-example">Focus first error · seed 7</button></div></section>`;
}
function scoreCell(value){const width=Math.max(0,Math.min(1,value??0))*100;return `<span class="score-cell">${num(value)}<div class="mini-track"><div class="mini-fill" style="width:${width}%"></div></div></span>`;}
function chosenLabel(s){return s.label==='incorrect'?badge('Incorrect','error'):s.label==='correct'?badge('Rule-valid'):badge(s.label==='attempted_incorrect'?'Attempted error':'Unverified','neutral');}
function stepDetail(data){
 const s=data.steps[S.step],byCap={[S.experiment]:s,[S.experiment==='cap5'?'cap17':'cap5']:data.comparisonSteps[S.step]};return `<div class="step-detail"><h3><span>Step ${s.index+1} · ${E(s.tool||'Assistant message')}</span>${chosenLabel(s)}</h3><p>${E(s.reason||'This step has no automatic correctness judgement. A score does not establish that it is correct.')}</p>${s.event===data.run.first_error?'<p><b>First labelled tool error in this run.</b> This is a verifier-based localization target, not a proven causal explanation.</p>':''}<div class="subgrid"><div><div class="caption">${s.tool?'Tool arguments':'Agent text'}</div><pre class="code-block">${s.tool?json(s.arguments):E(s.content)}</pre></div><div><div class="caption">Same step · saved scores · seed ${S.runSeed}</div><table class="metrics-table step-comparison"><thead><tr><th>Method</th><th class="number">3–5</th><th class="number">3–17</th></tr></thead><tbody>${['paper_nibs_cos_max','paper_nibs_cos_mean','tool_sim_nibs','paper_gibs_pdf','c4_gibs'].map(m=>`<tr data-step-method="${m}"><td>${names[m]}</td>${['cap5','cap17'].map(cap=>`<td class="number ${cap===S.experiment?'active-cap':''}">${num(score(byCap[cap],m))}</td>`).join('')}</tr>`).join('')}</tbody></table><p class="caption">Highlighted column is the active experiment. Scores rank steps; their absolute values are not calibrated probabilities.</p></div></div></div>`;
}
function renderSteps(data){
 const el=document.getElementById('run-tab');el.innerHTML=`<div class="callout"><p>Lower scores suggest steps to inspect. <b>NIBS uses successful references; learned predictions use the query graph only.</b> Preset labels use tool-only ranking; this table also includes messages. Scores are not calibrated correctness probabilities.</p></div><div class="step-row step-header"><span>#</span><span>Action / automatic label</span><span>NIBS Mean</span><span>GIBS</span><span>C4</span></div>${data.steps.map((s,i)=>`<button class="step-row ${i===S.step?'active':''} ${s.label==='incorrect'?'error':''}" data-step="${i}"><span class="step-index">${i+1}</span><span><span class="tool-name">${E(s.tool||'Assistant message')}</span><span class="label">${E(s.label)} ${s.event===data.run.first_error?'· first labelled tool error':''}</span></span>${scoreCell(score(s,'paper_nibs_cos_mean'))}${scoreCell(score(s,'paper_gibs_pdf'))}${scoreCell(score(s,'c4_gibs'))}</button>`).join('')}${stepDetail(data)}`;
 el.querySelectorAll('[data-step]').forEach(b=>b.addEventListener('click',()=>{S.step=Number(b.dataset.step);renderSteps(data);}));
}
function renderTranscript(data){
 document.getElementById('run-tab').innerHTML=`<details class="details"><summary>Task instructions and known information</summary><pre class="code-block">${json(taskById(data.run.task).instructions)}</pre></details><p class="caption">Whitelisted benchmark transcript. Provider metadata and credentials are excluded.</p>${data.messages.map(m=>`<div class="msg ${E(m.role)} ${data.steps[S.step].message_index===m.index?'active':''}"><div class="role">${E(m.role)} · message ${m.index}</div>${E(m.content)}${m.tool_calls.length?`<pre class="code-block">${json(m.tool_calls)}</pre>`:''}</div>`).join('')}`;
}
function graphSVG(data,matchedNodes=null,matchedEdges=null,interactive=true){
 const nodes=data.graph.nodes,depth={},incoming=new Map(nodes.map(n=>[n.id,[]]));
 data.graph.edges.forEach(e=>incoming.get(e.dst)?.push(e.src));
 for(const n of nodes)depth[n.id]=Math.max(0,...(incoming.get(n.id)||[]).map(id=>(depth[id]??0)+1));
 const levels={};for(const n of nodes)(levels[depth[n.id]]??=[]).push(n);
 const maxRows=Math.max(...Object.values(levels).map(a=>a.length)),height=Math.max(250,maxRows*72+40),width=Math.max(780,(Math.max(...Object.keys(levels).map(Number))+1)*190+20),pos={};
 for(const [level,arr] of Object.entries(levels))arr.forEach((n,i)=>pos[n.id]={x:20+Number(level)*190,y:20+(height-40-arr.length*72)/2+i*72});
 const edges=data.graph.edges.map(e=>{const a=pos[e.src],b=pos[e.dst],hit=matchedEdges?.has(e.id);return `<path d="M${a.x+145},${a.y+23} C${a.x+170},${a.y+23} ${b.x-25},${b.y+23} ${b.x},${b.y+23}" fill="none" stroke="${hit?'#188a7b':'#c4d2da'}" stroke-width="${hit?2.2:1.1}" opacity="${matchedEdges && !hit ? 0.5 : 1}"/>`;}).join('');
 const boxes=nodes.map(n=>{const q=pos[n.id],step=data.steps.find(s=>s.event===n.event),hit=matchedNodes?.has(n.id),value=step?score(step,S.teacher):null,selected=interactive&&step?.index===S.step;let fill='#fff';if(matchedNodes)fill=hit?'#daf0e7':'#f4f6f8';else if(step)fill=step.label==='incorrect'?'#fff0ed':step.label==='correct'?'#e8f4ef':'#fff';return `<g class="graph-node" ${interactive&&step?`data-node="${E(n.event)}" tabindex="0" role="button"`:'role="img"'} aria-label="${E(n.label)}" transform="translate(${q.x},${q.y})"><rect width="145" height="47" rx="7" fill="${fill}" stroke="${selected?'#007e83':hit?'#67aa96':'#cad8df'}" stroke-width="${selected?2:1}"/><text x="10" y="18" font-size="9" fill="#80919d">${E(n.event||'ROOT')} ${step?'· '+num(value):'· context'}</text><text x="10" y="34" font-size="10" fill="#1b3544">${E(n.label.length>22?n.label.slice(0,21)+'…':n.label)}</text><title>${E(n.text)}</title></g>`;}).join('');
 return `<div class="graph-wrap"><svg width="${width}" height="${height}" xmlns="http://www.w3.org/2000/svg" aria-label="Observed dependency graph">${edges}${boxes}</svg></div>`;
}
function bindNodes(data){document.querySelectorAll('#run-tab [data-node]').forEach(g=>{const pick=()=>{const s=data.steps.find(s=>s.event===g.dataset.node);if(s){S.step=s.index;renderRun(data.run.id);}};g.addEventListener('click',pick);g.addEventListener('keydown',e=>{if(e.key==='Enter')pick();});});}
function renderGraph(data){
 document.getElementById('run-tab').innerHTML=`<div class="panel-title"><div><h3>Actual saved-execution graph</h3><p class="caption">${data.graph.nodes.length} result/context nodes · ${data.graph.edges.length} operation edges · ${E(data.graph.topology)} projection. Scroll the graph and select an agent node.</p></div><label class="control"><span>Node score overlay</span><select id="graph-method">${['paper_gibs_pdf','c4_gibs','paper_nibs_cos_mean','paper_nibs_cos_max'].map(m=>option(m,names[m],S.teacher)).join('')}</select></label></div>${graphSVG(data)}<p class="caption top-space">Edges are inferred value dependencies, not verified causal reasoning. User/context nodes are not scored.</p>${stepDetail(data)}`;
 bind('graph-method','change',e=>{S.teacher=e.target.value;renderGraph(data);});bindNodes(data);
}
async function renderMCS(data){
 const el=document.getElementById('run-tab'),experiment=S.experiment;if(!isLearned(S.teacher))S.teacher='paper_gibs_pdf';const teacher=data.teachers[S.teacher];
 if(!teacher){el.innerHTML=`<div class="callout warn"><p>This query has no MCS training target because its task lacks three other successful training references. It still received held-out GCN predictions. References are not required at learned inference.</p></div>${stepDetail(data)}`;return;}
 if(S.ref>=teacher.references.length)S.ref=0;const pair=teacher.references[S.ref],ref=await loadRun(pair.id);if(S.page!=='explorer'||S.run!==data.run.id||S.tab!=='mcs'||S.experiment!==experiment)return;
 el.innerHTML=`<div class="callout"><p><b>Post-hoc teacher inspection.</b> These successful reference graphs generated targets. They were not inputs to this query’s held-out GCN prediction. MCS agreement is not independent correctness ground truth.</p></div><div class="filters"><label class="control"><span>Teacher rule</span><select id="teacher-method">${['paper_gibs_pdf','c4_gibs'].map(m=>option(m,names[m],S.teacher)).join('')}</select></label><label class="control"><span>Successful training reference</span><select id="teacher-ref">${teacher.references.map((r,i)=>option(String(i),`Reference ${i+1} · ${r.id.slice(0,8)}`,String(S.ref))).join('')}</select></label></div>${targetComparison(data)}<h3>Averaged target across ${teacher.references.length} references</h3><div class="target-tiles">${teacher.events.map((ev,i)=>`<button class="target-tile ${teacher.mask[i]>0?'matched':''} ${i===S.step?'active':''}" data-target="${i}"><small>Step ${i+1}</small>${num(teacher.mask[i])}</button>`).join('')}</div><div class="teacher-row"><div><h3>Query graph</h3><p class="caption">${Object.keys(pair.node_map).length} mapped nodes · ${Object.keys(pair.edge_map).length} mapped edges</p></div><div><h3>Reference passed the benchmark</h3><p class="caption">Same Task ${ref.run.task} · ${pair.id.slice(0,8)} · individual steps are not all human-verified.</p></div></div><h3>Matched structure in the query</h3>${graphSVG(data,new Set(Object.keys(pair.node_map)),new Set(Object.keys(pair.edge_map)))}<details class="details" open><summary>Successful reference graph · matched nodes highlighted</summary>${graphSVG(ref,new Set(Object.values(pair.node_map)),new Set(Object.values(pair.edge_map)),false)}</details>${stepDetail(data)}`;
 bind('teacher-method','change',e=>{S.teacher=e.target.value;S.ref=0;renderRun(data.run.id);});bind('teacher-ref','change',e=>{S.ref=Number(e.target.value);renderRun(data.run.id);});
 el.querySelectorAll('[data-target]').forEach(b=>b.addEventListener('click',()=>{S.step=Number(b.dataset.target);renderRun(data.run.id);}));bindNodes(data);
}
function targetComparison(data){
 const families={[S.experiment]:data.teachers,[S.experiment==='cap5'?'cap17':'cap5']:data.comparisonTeachers},event=data.steps[S.step].event;
 const cells=['cap5','cap17'].map(cap=>{const t=families[cap][S.teacher];if(!t)return '<td>N/A</td>';const i=t.events.indexOf(event),count=t.references.reduce((a,r)=>a+r.mask[event],0);return `<td><b>${num(t.mask[i])}</b> = ${count} / ${t.references.length}<small>${cap==='cap5'?'3–5':'3–17'} setting · successful-reference support</small></td>`;}).join('');
 return `<section class="target-comparison"><h3>Selected step ${S.step+1}: how its teacher target changes</h3><table class="metrics-table"><thead><tr><th>3–5 target</th><th>3–17 target</th></tr></thead><tbody><tr>${cells}</tr></tbody></table><p class="caption">Each target averages binary support indicators from its own reference set. GIBS uses matched result-node membership; C4 uses its stricter context support rule. These targets supervise training; they are not correctness labels. A selected step’s target can stay unchanged while its prediction changes, because the model is retrained against targets across the entire fitting set.</p></section>`;
}
function diagValue(obj,key){return key==='macro_auroc'?obj?.tool_calls?.macro_auroc:obj?.tool_calls?.localization?.[key];}
function diagnosis(){
 const diag=D.diagnostics;
 const comparisons=['paper_gibs_pdf','c4_gibs'].map(m=>{const a=diag.methods[m];return `<tr><td>${names[m]}</td><td class="number">${num(diagValue(a.direct_teacher,'macro_auroc'))}</td><td class="number">${num(mean(Object.values(a.learned).map(v=>diagValue(v,'macro_auroc'))))}</td><td class="number">${pct(diagValue(a.direct_teacher,'top1'))}</td><td class="number">${pct(mean(Object.values(a.learned).map(v=>diagValue(v,'top1'))))}</td></tr>`;}).join('');
 const unknown=D.summary.label_counts.unverified/D.summary.n_all_agent_steps;
 app.innerHTML=title('EVIDENCE / INTERPRETATION','Why didn’t GIBS win?','A more complex model is not guaranteed to outperform direct matching. Separate the measured differences from explanations that still need an ablation.')+
 `<div class="explain-grid"><div class="explain-card"><span class="proof">MEASURED / PROTOCOL</span><h2>Different information at scoring time</h2><p>NIBS compares with known-successful runs of the <b>same task</b>. The held-out GCN receives the query graph alone, with no successful references. It must generalize learned support patterns across task groups.</p></div><div class="explain-card"><span class="proof">MEASURED / DIAGNOSTIC</span><h2>A stronger teacher is not fully retained</h2><p>On the same 860 eligible queries, the direct C4 teacher has higher tool AUROC than its learned predictor. This measures a teacher-to-predictor gap. It does not isolate whether graph representation, optimization or task shift caused it.</p></div><div class="explain-card"><span class="proof">MEASURED / COVERAGE</span><h2>Most steps have no correctness label</h2><p><b>${pct(unknown)}</b> of all analysed agent steps are unverified. Automatic labels cover selected reads/writes and share field definitions with the structured matcher. High scores on this subset do not establish general reasoning reliability.</p></div><div class="explain-card"><span class="proof hypothesis">HYPOTHESIS / NOT PROVEN</span><h2>Representation and generalization limits</h2><p>Each model fits 509–526 graphs. Frozen BERT truncates at 256 tokens; inferred dependencies can miss conversational context. C4 field checks are teacher rules, not hard constraints enforced by GCN inference. Controlled ablations are needed.</p></div></div>
 <section class="panel top-space"><div class="panel-title"><div><h2>Teacher versus learned predictor</h2><p class="caption">Post-hoc diagnostic on exactly the same 860 target-eligible queries. 25 tasks with both labelled tool classes; 143 failed queries with labelled tool errors. Learner values are means over three seeds.</p></div>${badge('Separate diagnostic population','warn')}</div><div class="table-scroll"><table class="metrics-table"><thead><tr><th>Target family</th><th class="number">Direct teacher AUROC</th><th class="number">Learned AUROC</th><th class="number">Teacher Top-1</th><th class="number">Learned Top-1</th></tr></thead><tbody>${comparisons}</tbody></table></div><div class="callout"><p>Direct teachers use same-task successful references. Their masks are shown here for diagnosis only. <b>Do not substitute these 860-query values for the primary 911-query comparison.</b> The teacher’s own rule alignment is not human validation.</p></div></section>
 <div class="cols"><section class="panel"><h2>Inspect the optimization evidence</h2><p class="caption">Saved training and validation loss. This optimizes agreement with teacher masks, not step-label AUROC.</p><label class="control top-space"><span>Saved checkpoint</span><select id="history-key">${Object.keys(D.histories).map(k=>option(k,k,Object.keys(D.histories)[0])).join('')}</select></label><div id="history-chart"></div></section><section class="panel"><h2>What to do before claiming a cause</h2><div class="finding"><div class="kicker">01 / INDEPENDENT REVIEW</div><p>Review representative correct and incorrect steps, especially same-tool wrong arguments, messages and reference-quality flags.</p></div><div class="finding"><div class="kicker">02 / CONTROLLED ABLATIONS</div><p>Change graph context, features, target construction or reference count one at a time. Preserve the original experiment and avoid choosing settings using these test results.</p></div><div class="finding"><div class="kicker">03 / HONEST COMPARISON</div><p>Keep NIBS, tool_sim, random and last-step-first. Report common-population and broader learned coverage separately.</p></div><div class="finding"><div class="kicker">04 / FINISH EVALUATION</div><p>ACC@80% and ECE remain unimplemented. Define probability mapping for cosine scores and keep calibration fitting on validation data.</p></div></section></div>`;
 bind('history-key','change',e=>historyChart(e.target.value));historyChart(Object.keys(D.histories)[0]);
}
function historyChart(key){
 const h=D.histories[key],arr=h.history,w=620,hh=210,pad=32,values=arr.flatMap(x=>[x.train_loss,x.validation_loss]),lo=Math.min(...values),hi=Math.max(...values),x=i=>pad+i/Math.max(1,arr.length-1)*(w-2*pad),y=v=>hh-pad-(v-lo)/Math.max(.001,hi-lo)*(hh-2*pad);
 const path=field=>arr.map((v,i)=>`${i?'L':'M'}${x(i)},${y(v[field])}`).join(' ');
 document.getElementById('history-chart').innerHTML=`<svg class="training-chart" viewBox="0 0 ${w} ${hh}" role="img" aria-label="Training and validation loss for ${E(key)}"><line x1="${pad}" x2="${w-pad}" y1="${hh-pad}" y2="${hh-pad}" stroke="#d5e0e6"/><path d="${path('train_loss')}" fill="none" stroke="#198885" stroke-width="2"/><path d="${path('validation_loss')}" fill="none" stroke="#b39457" stroke-width="2"/><line x1="${x(h.best_epoch-1)}" x2="${x(h.best_epoch-1)}" y1="${pad}" y2="${hh-pad}" stroke="#8b99a6" stroke-dasharray="3 4"/><text x="${pad}" y="${hh-7}" font-size="10" fill="#708391">Epoch 1</text><text x="${w-pad}" y="${hh-7}" text-anchor="end" font-size="10" fill="#708391">${h.epochs} epochs</text></svg><div class="legend"><span><i style="background:#198885"></i>Training loss</span><span><i style="background:#b39457"></i>Validation loss</span><span>Saved best: epoch ${h.best_epoch}</span></div><p class="caption top-space">Weights changed by up to ${h.max_weight_change.toFixed(3)}. This is a trained model, not a placeholder checkpoint.</p>`;
}
function guide(){
 const points=[['Generate repeated executions','50 Airline tasks × 20 runs. Assistant and user simulator are ASU-hosted Qwen3.8-27B, with temperatures 1.0 and 0.0.'],['Keep evaluation groups apart','Four held-out task-group folds prevent the scored task group from entering that model’s fitting or early stopping.'],['Choose successful references',`For the active ${D.meta.experiment_label} setting, choose at least three and at most ${D.meta.teacher_max_references} other successful training runs of the same task. The actual maximum is ${S.experiment==='cap17'?'16':'5'} here. These limits are project choices, not paper requirements.`],['Compute MCS and soft targets','Compare the query graph separately with each reference. For paper GIBS, four node matches out of five give target 0.8. C4 adds stricter rules and all-incoming-edge support.'],['Train the small graph predictor','Two target methods × four folds × three seeds = 24 saved checkpoints. BERT and DeBERTa remain frozen; Qwen is not fine-tuned.'],['Score and compare','All 1,000 trajectories receive held-out learned predictions. 911 have enough references for the common NIBS comparison. Metrics use automatic labels; human review is pending.']];
 app.innerHTML=title('PRESENTATION NOTES / PLAIN ENGLISH','The experiment in six steps.','Use this explanation during your Phase 2 demonstration. This is a transfer of paper methods to Airline agent data, with C4 as a project extension.',`<button class="button" id="copy-notes">Copy summary</button>`)+`<div class="cols"><div class="guide-list">${points.map(([a,b])=>`<div class="guide-item"><div><h3>${a}</h3><p>${b}</p></div></div>`).join('')}</div><div><section class="panel"><h2>Three counts, three meanings</h2><div class="finding"><h3>1,000 generated trajectories</h3><p>The full collection. 680 official passes and 320 failures. The 68% task pass rate is not a confidence-method accuracy.</p></div><div class="finding"><h3>860 target-eligible queries</h3><p>Seven tasks lack three successful training references. Their 140 queries have no training target but are still scored by held-out GCNs.</p></div><div class="finding"><h3>911 common comparison queries</h3><p>NIBS uses a larger successful evaluation-reference bank. Missing-reference cases are not assigned fabricated scores.</p></div></section><section class="panel"><h2>What the metrics mean</h2><div class="finding"><h3>AUROC</h3><p>Ranks incorrect steps below correct steps. 0.5 is random ordering; 1.0 is perfect ordering. It is not pass rate or thresholded accuracy.</p></div><div class="finding"><h3>First-error Top-1</h3><p>How often the lowest-confidence candidate points to the first labelled tool error in an eligible failed run. A later error can rank lowest even when AUROC is strong.</p></div><div class="finding"><h3>Confidence</h3><p>Agreement with successful patterns or learned teacher support. A score of 0.8 is not verified 80% correctness.</p></div></section></div></div><section class="panel top-space"><h2>Phase 2 evidence and remaining work</h2><p class="caption">Working prototype on real benchmark data, frozen task-group splits, completed baseline comparison, genuine MCS artifacts, 24 trained checkpoints and saved per-step predictions. Independent review, missing paper metrics, stakeholder acceptance and Phase 3 operational hardening remain separate work.</p></section><section class="panel"><h2>Sources and provenance</h2><p class="caption">Data: pinned tau2-bench collection. Primary methods: supplied paper 2605.19228v2, Eq. 2 / Eq. 6 and App. C.2 / D.3. Agent graph, fusion, reference cap and C4 rules are implementation choices. Export derived from the completed summary and unchanged frozen input.</p><div class="pill-row"><a class="button" href="data/${S.experiment}/REPORT.md" download>Download actual report</a><a class="button" href="data/${S.experiment}/per_task.csv" download>Download 50-task results</a><a class="button" href="data/${S.experiment}/diagnostics.json" download>Download teacher diagnostic</a></div><p class="source-tag">Input SHA256: ${E(D.meta.snapshot_sha256)}<br>Summary SHA256: ${E(D.meta.summary_sha256)}</p></section>`;
 const worked=`<section class="panel top-space"><div class="panel-title"><div><h2>Worked example: how a GIBS target is made</h2><p class="caption">Illustration only. These checkboxes are not recorded benchmark results and never change the saved experiment.</p></div>${badge('Try changing a match','neutral')}</div><p class="small">Suppose a training execution reads a profile, reads a reservation, then books a passenger. Compare its graph against five successful training runs of the same task. For paper GIBS, a checkbox means the step’s result node belongs to that pair’s MCS.</p><div class="table-scroll"><table class="metrics-table"><thead><tr><th>Query step</th>${[1,2,3,4,5].map(i=>`<th>Ref ${i}</th>`).join('')}<th class="number">Target</th></tr></thead><tbody>${['Read profile','Read reservation','Book passenger'].map((label,i)=>`<tr><td>${label}</td>${[0,1,2,3,4].map(j=>`<td><input class="toy-match" type="checkbox" data-row="${i}" aria-label="${label}, reference ${j+1} matched" ${j<[5,4,1][i]?'checked':''}></td>`).join('')}<td class="number" id="toy-target-${i}"></td></tr>`).join('')}</tbody></table></div><div class="callout"><p id="toy-vector"></p></div><div class="guide-list"><div class="guide-item"><div><h3>Turn each run into a graph</h3><p>Nodes represent observed results, edges represent operations and inferred dependencies. A query may pass or fail; references must be benchmark-successful.</p></div></div><div class="guide-item"><div><h3>Compute one MCS per query/reference pair</h3><p>DeBERTa estimates similarity. The approximate graph matcher checks candidate nodes and edges at threshold 0.7, then builds consistent matches.</p></div></div><div class="guide-item"><div><h3>Average support to create the teacher vector</h3><p>Five matches out of five give 1.0; four give 0.8; one gives 0.2. This is structural agreement, not an independent correctness label.</p></div></div><div class="guide-item"><div><h3>Train against the fixed vector</h3><p>Frozen BERT supplies features. The GCN/prediction layers output scores; Equation 6 supplies loss and Adam updates the weights. Batches contain eight query graphs. One epoch is one pass through the training set.</p></div></div><div class="guide-item"><div><h3>Select with validation; score a held-out graph</h3><p>Early stopping saves the best validation checkpoint. The held-out task group does not enter fitting. Inference uses only the query graph, without MCS or references.</p></div></div><div class="guide-item"><div><h3>Evaluate with separate labels</h3><p>Compare predicted scores with independent step judgements. Agreement with the teacher by itself does not establish real error-detection quality.</p></div></div></div></section>`;
 document.querySelector('.guide-list').parentElement.insertAdjacentHTML('afterend',worked);
 if(window.GIBS_WALKTHROUGH_HTML)document.getElementById('toy-vector').closest('section').insertAdjacentHTML('afterend','<details class="details worked-detail" id="full-gibs-walkthrough"><summary>Read the complete GIBS example: every stage, from tool calls to evaluation</summary><p>This teaching walkthrough uses five illustrative references and historical 3–5 checkpoint numbers. For the active experiment, use the actual explorer scores and references above.</p>'+window.GIBS_WALKTHROUGH_HTML+'</details>');
 const updateToy=()=>{const values=[0,1,2].map(i=>document.querySelectorAll(`.toy-match[data-row="${i}"]:checked`).length/5);values.forEach((v,i)=>document.getElementById('toy-target-'+i).textContent=v.toFixed(1));document.getElementById('toy-vector').textContent='Teacher vector: ['+values.map(v=>v.toFixed(1)).join(', ')+']. These are the per-step supervision targets used for the illustrative training query.';};
 document.querySelectorAll('.toy-match').forEach(c=>c.addEventListener('change',updateToy));updateToy();
 bind('copy-notes','click',async()=>{const text=points.map(([a,b],i)=>`${i+1}. ${a}: ${b}`).join('\n');try{await navigator.clipboard.writeText(text);toast('Summary copied.');}catch{downloadText('phase2-summary.txt',text);toast('Summary saved as a text file.');}});
}
function downloadText(name,text){const url=URL.createObjectURL(new Blob([text],{type:'text/plain'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);}
bind('experiment','change',e=>changeExperiment(e.target.value));
window.addEventListener('hashchange',()=>{decodeRoute();render();});decodeRoute();render();
})();
